import React from 'react';
import './Pagination.scss';
export interface PaginationProps {
    /**
     * Identifying value for the pagination.
     */
    id: string;
    /**
     * Determines the current page of the pagination
    */
    /**
     * Determines the total number of records
    */
    totalRecords?: number;
    /**
     * Determines the total page of the pagination
    */
    totalPages: number;
    /**
     * Label for current page over total pages in type *responsive*
    */
    pageInfoLabel?: string;
    /**
     *Page change event of the pagination
    */
    onPageChange: (page: number) => void;
    /**
     *Determines the total items Per Page
    */
    onItemsPerPageChange?: (items: number) => void;
    /**
    *Determines the total items Per Page
   */
    /**
     * Determines the variant of the pagination: circle, square.
    */
    variant?: "icon" | "label" | "label-and-icon";
    /**
    * Determines the type of the pagination.
    */
    type: "table" | "responsive" | "slider";
    /**
     * Determines the shape of the pagination: circle, square.
    */
    shape?: "circle" | "square";
    /**
     * Determines the colour of the pagination: primary, secondary, tertiary.
    */
    colour?: "primary" | "secondary" | "tertiary";
    /**
    * Determines the outline or non outline of the pagination
   */
    outline?: "outline" | "none";
    /**
     * Determines whether to show rows per page dropdown or not
     */
    showRowsPerPage?: boolean;
    /**
    * Optional width for the "Go To Page" TextField
    * Example: "150px", "10rem"
    */
    goToPageInputWidth?: string;
    /**
   * Controls the alignment of pagination buttons: left or right
   */
    paginationButtonsPosition?: "left" | "right";
}
declare const Pagination: React.FC<PaginationProps>;
export default Pagination;
